window.FICHAS = [{"n":1,"c":1,"t":"Conta de água subiu e não aparece vazamento","d":"O consumo subiu de um mês para o outro, sem mancha, poça ou barulho de água.","si":["Conta dobrou sem mudar a rotina","Nenhuma mancha ou poça à vista","Caixa-d'água sempre cheia","Ponteiro do hidrômetro não para"],"ca":["Descarga passando água ao vaso","Boia da caixa-d'água não veda","Vazamento no tubo enterrado","Tubo ou conexão na parede","Torneira ou registro pingando","Erro de leitura ou do hidrômetro"],"sis":"Água fria","fe":"Hidrômetro e corante","at":"Antes de quebrar a parede","a":"Faça o teste do hidrômetro e do corante. Muitas vezes o vilão é a descarga, não o cano da parede."},{"n":2,"c":1,"t":"Mancha de umidade na parede perto do banheiro","d":"A parede do cômodo ao lado do banheiro manchou, com bolor ou tinta estufando.","si":["Mancha cresce depois do banho","Tinta estufada ou descascando","Cheiro de mofo no cômodo","Rodapé escuro ou soltando"],"ca":["Rejunte do box com falha","Conexão do registro ou chuveiro","Ralo ou caixa sifonada vazando","Tubo de água furado ou trincado","Esgoto da pia ou do vaso","Umidade do solo subindo"],"sis":"Água fria e esgoto","fe":"Medidor de umidade","at":"Antes de quebrar a parede","a":"A mancha quase nunca fica em cima do vazamento: a água corre dentro da parede. Ache o ponto antes de abrir."},{"n":3,"c":1,"t":"Mancha no teto embaixo do banheiro de cima","d":"O teto do andar de baixo mancha ou pinga bem embaixo do banheiro do piso superior.","si":["Mancha embaixo do box ou do vaso","Pinga depois do banho","Gesso ou pintura estufando","Cheiro de esgoto às vezes"],"ca":["Ralo ou caixa sifonada vazando","Rejunte do box com falha","Anel de vedação do vaso","Tubo de água no piso ou parede","Esgoto mal encaixado na laje","Impermeabilização rompida"],"sis":"Água fria e esgoto","fe":"Corante e lanterna","at":"Antes de quebrar o piso","a":"Teste ponto por ponto com corante, olhando por baixo. Quebrar o piso sem achar o ponto vira reforma inteira."},{"n":4,"c":1,"t":"Vazamento no cavalete ou no hidrômetro","d":"Água escorrendo no cavalete da entrada, em volta do relógio ou do registro.","si":["Poça embaixo do cavalete","Gotejando na porca do relógio","Registro molhado na haste","Muro úmido perto da entrada"],"ca":["Vedação da porca do hidrômetro","Registro vazando pela haste","Rosca ou conexão do cavalete","Tubo da casa após o registro","Cavalete rachado ou batido","Ramal da rua antes do relógio"],"sis":"Água fria","fe":"Chave de grifo e pano","at":"Antes de trocar a peça","a":"Veja de que lado do registro está o pingo. Do relógio para trás é da companhia; mexer ali pode gerar multa."},{"n":5,"c":1,"t":"Piso úmido ou piso de madeira estufando","d":"Rejunte sempre úmido ou laminado e taco estufando, sem nenhuma poça aparente.","si":["Rejunte escuro que não seca","Laminado ou taco estufado","Piso frio com manchas","Cheiro de mofo perto do chão"],"ca":["Tubo de água sob o piso","Água de limpeza pelo rejunte","Tubo de água quente sob o piso","Ralo ou esgoto vazando","Dreno do ar-condicionado solto","Umidade do solo subindo"],"sis":"Água fria e quente","fe":"Medidor de umidade","at":"Antes de quebrar o piso","a":"Faça o mapa de umidade e o teste do hidrômetro. Quebrar o piso inteiro sem achar o pico é prejuízo certo."},{"n":6,"c":1,"t":"Água brotando no quintal ou na calçada","d":"Terra sempre encharcada ou água minando no quintal, na garagem ou na calçada da frente.","si":["Terra sempre molhada num ponto","Água limpa minando do chão","Grama mais verde numa faixa","Calçada afundando ou trincada"],"ca":["Ramal enterrado rompido","Tubo de alimentação da caixa","Rede da rua antes do relógio","Esgoto ou caixa de inspeção","Água de chuva acumulada","Lençol freático alto"],"sis":"Água fria e esgoto","fe":"Haste de escuta","at":"Antes de quebrar o piso","a":"Descubra se a água é da rede, do esgoto ou da chuva. Cavar o quintal atrás do cano errado só aumenta o buraco."},{"n":7,"c":1,"t":"Água embaixo da pia, com o gabinete molhado","d":"O fundo do gabinete fica molhado ou estufado; às vezes só molha quando a pia é usada.","si":["Fundo do gabinete estufado","Poça depois de lavar a louça","Pingo no sifão ou no flexível","Cheiro de umidade no armário"],"ca":["Sifão frouxo ou sem anel","Válvula de escoamento vazando","Engate flexível ou rosca","Rosca da torneira na bancada","Conexão de esgoto na parede","Vedação da borda da cuba"],"sis":"Água fria e esgoto","fe":"Papel toalha e lanterna","at":"Antes de trocar a peça","a":"Forre o gabinete com papel e use a pia. A marca no papel mostra de onde vem o pingo antes de trocar qualquer peça."},{"n":8,"c":1,"t":"Box vazando para fora ou para o cômodo ao lado","d":"Depois do banho, a água passa a soleira, molha o banheiro ou aparece no cômodo vizinho.","si":["Poça fora do box após o banho","Soleira sempre molhada","Rodapé do cômodo ao lado úmido","Água demora a escoar no box"],"ca":["Caimento do piso errado","Vedação do vidro ou perfil","Rejunte do piso ou da parede","Ralo pequeno ou sujo","Soleira ou baguete baixa","Impermeabilização falha"],"sis":"Água servida","fe":"Nível e balde","at":"Antes de quebrar a parede","a":"Molhe uma parte de cada vez: piso, vidro, rejunte e soleira. Cada teste aponta um reparo diferente e mais barato."},{"n":9,"c":1,"t":"Parede molhada em volta do registro do chuveiro","d":"Azulejo ou parede úmida em volta do registro, da canopla ou da saída do chuveiro.","si":["Rejunte escuro em volta do registro","Mancha atrás da parede do box","Pinga na canopla ao abrir","Piora com o chuveiro ligado"],"ca":["Água entrando pela canopla","Vazamento pela haste do registro","Rosca do braço do chuveiro","Conexão de entrada do registro","Tubo da subida do chuveiro","Corpo do registro trincado"],"sis":"Água fria e quente","fe":"Chave de registro","at":"Antes de quebrar a parede","a":"Tire a canopla e olhe a haste primeiro. Muitas vezes é o reparo ou o rejunte, não o corpo do registro."},{"n":10,"c":1,"t":"Vazamento que só aparece com água quente","d":"A parede ou o forro só molham quando a casa usa a água quente do aquecedor ou do boiler.","si":["Mancha só depois do banho quente","Seca com o aquecedor desligado","Estalos na parede","Cano amolecido ou deformado"],"ca":["PVC comum na água quente","Termofusão mal feita","Conexão do aquecedor ou boiler","Dilatação sem folga","Temperatura alta demais","Escape da válvula de alívio"],"sis":"Água quente","fe":"Termômetro e manômetro","at":"Antes de quebrar a parede","a":"Descubra o material e a temperatura antes de abrir. PVC comum em água quente vai vazar de novo em outro ponto."},{"n":11,"c":1,"t":"Cano furado depois de furar a parede","d":"Logo depois de furar para prateleira, quadro ou armário, a parede começou a molhar ou jorrar.","si":["Água saindo pelo furo da bucha","Mancha logo abaixo do furo","Pressão caiu de repente","Parafuso ou bucha molhados"],"ca":["Broca furou o tubo de água","Parafuso entrou no tubo","Tubo trincado pela batida","Furo no tubo de esgoto","Tubo de água quente atingido","Fio elétrico junto no furo"],"sis":"Água fria ou quente","fe":"Detector e luva de correr","at":"Antes de quebrar a parede","a":"O furo já mostra o ponto: abra só em volta dele. Remendo com cola ou fita em tubo com pressão volta a vazar."},{"n":12,"c":1,"t":"Rosca vazando mesmo com fita veda rosca","d":"A conexão roscável foi vedada e apertada, mas continua pingando ou suando na rosca.","si":["Pingo na rosca recém-vedada","Rosca suando gota a gota","Conexão trincou no aperto","Vazou depois de reapertar"],"ca":["Fita pouca ou no sentido errado","Aperto demais na conexão","Rosca espanada ou amassada","Conexão trincada","Rosca de metal em PVC","Roscas incompatíveis"],"sis":"Água fria ou quente","fe":"Fita veda rosca e chave","at":"Antes de trocar a peça","a":"Mais fita e mais força não resolvem: trincam a conexão. Refaça a vedação no sentido certo e aperte só o necessário."},{"n":13,"c":1,"t":"Emenda soldável nova vazando","d":"Conexão de PVC colada há pouco tempo pinga ou solta quando a água é liberada.","si":["Pinga na boca da conexão","Vazou logo ao abrir a água","Tubo soltou da bolsa","Adesivo escorrido por fora"],"ca":["Água liberada antes da cura","Tubo sem lixar ou limpar","Tubo não encostou no fundo","Adesivo pouco ou vencido","Corte torto ou com rebarba","Tubo e conexão incompatíveis"],"sis":"Água fria","fe":"Lixa e adesivo plástico","at":"Antes de trocar a peça","a":"Emenda soldável que vaza não tem remendo: corte e refaça. Lixe, limpe, encaixe até o fundo e espere a cura."},{"n":14,"c":1,"t":"Cano rachado ou estourado","d":"O tubo abriu de repente, com jato ou trinca longa, às vezes depois de batidas no encanamento.","si":["Jato forte ou trinca no tubo","Batidas no cano ao fechar torneira","Tubo ressecado e desbotado","Pressão muito forte na casa"],"ca":["Pressão alta da rua","Golpe de aríete","Tubo exposto ao sol","Tubo velho ou fino","Impacto ou peso no tubo","Acomodação da estrutura"],"sis":"Água fria ou quente","fe":"Manômetro e luva de correr","at":"Antes de trocar a peça","a":"Trocar só o pedaço rachado não basta se a causa é pressão ou golpe. Meça a pressão antes, senão estoura de novo."},{"n":15,"c":1,"t":"Infiltração só em dia de chuva","d":"A mancha ou a goteira surge só quando chove e seca nos dias sem chuva.","si":["Mancha aparece depois da chuva","Seca em dias sem chuva","Goteira perto de calha ou janela","Hidrômetro parado com tudo fechado"],"ca":["Calha ou rufo entupido ou furado","Telha quebrada ou deslocada","Laje sem impermeabilização","Janela ou peitoril sem vedação","Ralo da laje ou sacada entupido","Trinca na fachada"],"sis":"Água de chuva","fe":"Mangueira e lanterna","at":"Antes de quebrar a parede","a":"Só molha com chuva e o hidrômetro fica parado? Não é cano. Teste calha, telha e janela com mangueira."},{"n":16,"c":1,"t":"Rodapé úmido com tinta estufando na base","d":"A parte de baixo da parede fica úmida, com tinta descascando e pó branco perto do rodapé.","si":["Tinta estufada até meio metro","Pó branco ou salitre na parede","Rodapé solto ou escurecido","Piora em época de chuva"],"ca":["Umidade do solo subindo","Calçada externa sem caimento","Tubo de água sob o piso","Ralo ou esgoto próximo","Água de limpeza no rodapé","Jardineira encostada na parede"],"sis":"Solo e água fria","fe":"Medidor de umidade","at":"Antes de quebrar o piso","a":"Mancha contínua na base costuma ser umidade do solo, não cano. Meça em alturas diferentes antes de abrir o piso."},{"n":17,"c":1,"t":"Aquecedor ou boiler pingando pela válvula","d":"A válvula de segurança do boiler ou do aquecedor solta água de vez em quando ou sem parar.","si":["Pinga na válvula de segurança","Pinga mais quando aquece","Água muito quente na torneira","Estalos ou chiado no boiler"],"ca":["Pressão de entrada alta","Dilatação da água aquecida","Sujeira na sede da válvula","Termostato desregulado","Válvula gasta ou cansada","Retenção na entrada de água"],"sis":"Água quente","fe":"Termômetro e manômetro","at":"Antes de trocar a peça","a":"A válvula pingando muitas vezes está fazendo o trabalho dela. Meça pressão e temperatura antes de trocar a peça."},{"n":18,"c":1,"t":"Vizinho de baixo reclama de mancha no teto","d":"Em prédio, o apartamento de baixo tem mancha ou goteira e aponta o seu banheiro ou cozinha.","si":["Mancha no teto do vizinho","Goteira depois de banho ou descarga","Forro de gesso do vizinho manchado","Condomínio pedindo vistoria"],"ca":["Ralo ou caixa sifonada","Box com rejunte ou manta falhando","Anel de vedação do vaso","Ramal de água do apartamento","Prumada do prédio","Máquina de lavar ou tanque"],"sis":"Água fria e esgoto","fe":"Corante e lanterna","at":"Antes de quebrar o piso","a":"Teste ponto por ponto com corante, olhando de baixo. Pode ser a prumada do prédio, e aí o reparo não é do morador."},{"n":19,"c":1,"t":"Cano de ferro galvanizado minando em vários pontos","d":"Casa antiga com cano de ferro: pingos e manchas surgem em pontos diferentes, um após o outro.","si":["Vazamento novo a cada mês","Água amarelada ao abrir","Pressão fraca na casa toda","Ferrugem nas roscas aparentes"],"ca":["Corrosão de fim de vida","Roscas corroídas","Mistura de metais na linha","Remendo forçando o tubo velho","Pressão alta na rede","Água agressiva ou com sedimento"],"sis":"Água fria","fe":"Chave de grifo e manômetro","at":"Antes de trocar a peça","a":"Trocar só o trecho furado em ferro velho vira chamado toda semana. Mostre o tubo por dentro antes de orçar."},{"n":20,"c":1,"t":"Filtro ou purificador de parede pingando","d":"O filtro ou o purificador da cozinha goteja na conexão, na carcaça ou no engate da torneira.","si":["Pingo na conexão do filtro","Carcaça molhada por fora","Mangueira encharcada","Vaza depois de trocar o refil"],"ca":["Anel do refil fora do lugar","Mangueira mal encaixada","Pressão alta da rua","Derivação ou adaptador","Mangueira cortada torta","Carcaça trincada"],"sis":"Água potável","fe":"Chave do refil e pano","at":"Antes de trocar a peça","a":"Na maioria das vezes é o anel do refil ou a mangueira mal encaixada. Revise a vedação antes de condenar o aparelho."},{"n":21,"c":1,"t":"Água no chão atrás da máquina de lavar parada","d":"Poça atrás ou embaixo da máquina mesmo com ela desligada, sem estar lavando.","si":["Poça com a máquina desligada","Torneira da máquina molhada","Mangueira úmida na rosca","Rejunte atrás da máquina escuro"],"ca":["Vedação da mangueira de entrada","Torneira da máquina pingando","Rosca da torneira na parede","Mangueira de entrada rachada","Válvula de entrada da máquina","Mangueira de saída mal presa"],"sis":"Água fria","fe":"Pano e lanterna","at":"Antes de trocar a peça","a":"Máquina parada e poça no chão? Confira a borrachinha da mangueira e a torneira antes de chamar assistência."},{"n":22,"c":1,"t":"Mancha na parede atrás do vaso sanitário","d":"Parede úmida ou azulejo escuro atrás do vaso, da válvula de descarga ou da caixa acoplada.","si":["Mancha atrás ou ao lado do vaso","Piora depois de dar descarga","Rejunte escuro perto do piso","Registro da caixa molhado"],"ca":["Flexível ou registro da caixa","Tubo de descarga da válvula","Anel de vedação do vaso","Tubo de alimentação embutido","Esgoto ou ventilação na parede","Condensação na caixa acoplada"],"sis":"Água fria e esgoto","fe":"Corante e papel toalha","at":"Antes de quebrar a parede","a":"Teste flexível, corante e tubo de descarga primeiro. Muitos desses casos se resolvem sem abrir a parede."},{"n":23,"c":1,"t":"Forro de gesso manchado sem banheiro em cima","d":"Mancha ou gota no forro de um cômodo sem nenhuma área molhada em cima.","si":["Mancha redonda no gesso","Pinga mais com o ar ligado","Aparece com chuva ou banho quente","Gesso amolecido ou caindo"],"ca":["Dreno do ar-condicionado","Caixa-d'água no entreforro","Tubo de água passando no forro","Telhado, calha ou rufo","Tubo de água quente no forro","Condensação em tubo frio"],"sis":"Água e dreno","fe":"Lanterna e escada","at":"Antes de abrir o forro","a":"Sem banheiro em cima, o primeiro suspeito é o dreno do ar-condicionado. Teste o dreno antes de cortar o gesso."},{"n":24,"c":1,"t":"Mofo no teto do banheiro sem vazamento","d":"Pontos pretos de mofo no teto e nos cantos do banheiro, sem goteira nem mancha de vazamento.","si":["Pontos pretos no teto e cantos","Espelho embaçado por muito tempo","Pintura descascando no teto","Sem goteira nem mancha marrom"],"ca":["Banho quente sem ventilação","Exaustor fraco ou desligado","Porta e janela fechadas no banho","Laje fria sem isolamento","Tinta comum no teto","Vazamento real acima"],"sis":"Ventilação","fe":"Higrômetro e lanterna","at":"Antes de quebrar a parede","a":"Mofo preto e seco no teto quase sempre é vapor do banho, não cano. Resolva a ventilação antes de abrir."},{"n":25,"c":1,"t":"A mancha voltou depois do conserto","d":"O vazamento foi reparado, mas a mancha continua, cresce de novo ou volta depois de pintar.","si":["Mancha não sumiu após o reparo","Tinta nova estufou de novo","Pó branco na parede","Cliente acha que não resolveu"],"ca":["Parede ainda secando","Havia um segundo vazamento","Pintura antes de secar","Salitre na parede","O reparo não segurou","A causa era chuva ou solo"],"sis":"Água fria e esgoto","fe":"Medidor de umidade","at":"Antes de quebrar a parede","a":"Parede molhada leva semanas para secar. Meça e acompanhe por data antes de abrir de novo o mesmo lugar."},{"n":26,"c":2,"t":"Ralo com mau cheiro sem estar entupido","d":"O ralo escoa normal, mas o banheiro fica com cheiro de esgoto, pior em dias quentes.","si":["Cheiro de esgoto no banheiro","Ralo escoando normalmente","Pior em ralo pouco usado","Cheiro some ao jogar água"],"ca":["Fecho hídrico secou","Cabelo e lodo no ralo","Caixa sifonada mal vedada","Ralo seco ligado no esgoto","Falta de ventilação no esgoto","Esgoto vazando sob o piso"],"sis":"Esgoto","fe":"Lanterna e balde","at":"Antes de quebrar o piso","a":"Encha o ralo de água e espere. Ralo pouco usado seca o fecho hídrico e o cheiro sobe por ali."},{"n":27,"c":2,"t":"Pia da cozinha escoando devagar","d":"A água demora a descer na cuba e às vezes volta suja ou com cheiro de gordura.","si":["Água parada na cuba depois de lavar","Ronco ou borbulho ao escoar","Cheiro de gordura na pia","Piora depois de lavar panela"],"ca":["Gordura e resto de comida no sifão","Gordura grudada no tubo da parede","Caixa de gordura cheia","Válvula ou grelha obstruída","Tubo com pouco caimento","Saída da caixa de gordura entupida"],"sis":"Esgoto","fe":"Balde e mola desentupidora","at":"Antes de quebrar a parede","a":"Abra o sifão e a caixa de gordura primeiro. Na pia da cozinha, a gordura costuma estar num desses dois pontos."},{"n":28,"c":2,"t":"Caixa de gordura transbordando ou cheirando","d":"A caixa de gordura do quintal transborda, enche rápido ou solta cheiro forte em volta.","si":["Gordura saindo pela tampa","Cheiro de comida podre no quintal","Pia da cozinha escoando devagar","Caixa enche logo após limpar"],"ca":["Limpeza atrasada","Saída da caixa obstruída","Tampa sem vedação","Rede adiante entupida","Outros pontos ligados na caixa","Caixa pequena para o uso"],"sis":"Esgoto","fe":"Pá, balde e luva","at":"Antes de quebrar o piso","a":"Limpe a caixa e teste a saída e a caixa seguinte. Troque ou mova a caixa só depois de ver onde a água para."},{"n":29,"c":2,"t":"Vaso sanitário entupido","d":"Ao dar descarga, a água sobe no vaso e demora a descer ou não desce.","si":["Água sobe até a borda na descarga","Desce muito devagar","Ralo do banheiro pode voltar água","Começou de uma vez, sem aviso"],"ca":["Excesso de papel ou dejetos","Objeto jogado no vaso","Ramal entupido até a caixa","Caixa de inspeção cheia","Pouca água na descarga","Anel de vedação deslocado"],"sis":"Esgoto","fe":"Desentupidor e mola","at":"Antes de trocar a peça","a":"Abra a caixa de inspeção antes de mexer no vaso: se ela estiver cheia, o problema está na rede, não na louça."},{"n":30,"c":2,"t":"Vaso que entope toda semana","d":"O vaso desentope, funciona alguns dias e volta a entupir com uso normal.","si":["Entope com uso normal da casa","Desentupidor resolve por pouco tempo","Descarga sempre parece fraca","Às vezes borbulha no ralo"],"ca":["Pouca água por descarga","Ramal com pouco caimento","Tubo de 75 em vez de 100","Falta de ventilação","Vaso antigo com caixa econômica","Tubo quebrado ou com raiz"],"sis":"Esgoto","fe":"Nível e câmera de inspeção","at":"Antes de quebrar o piso","a":"Regule a água da descarga e passe a câmera. Entupimento repetido tem causa fixa, e ela pode estar longe do vaso."},{"n":31,"c":2,"t":"Ralo do box escoando devagar","d":"Durante o banho a água acumula no box e demora para descer pelo ralo.","si":["Água acumula no box no banho","Desce devagar depois de fechar","Borda do box molha o banheiro","Cheiro de sabão e cabelo"],"ca":["Cabelo e sabão na grelha e no copo","Caixa sifonada suja","Tubo do ralo à caixa obstruído","Caimento ruim do piso","Ralo pequeno para a ducha","Saída da caixa sifonada obstruída"],"sis":"Esgoto","fe":"Gancho de cabelo e balde","at":"Antes de quebrar o piso","a":"Limpe ralo e caixa sifonada e faça o teste do balde. Quebrar o piso só se o caimento estiver errado de verdade."},{"n":32,"c":2,"t":"Água volta pelo ralo quando dão descarga","d":"Ao dar descarga no vaso, a água sobe ou espirra pelo ralo do banheiro.","si":["Água sobe no ralo na descarga","Ralo borbulha ou faz ronco","Vaso também desce devagar","Às vezes volta com sujeira"],"ca":["Obstrução depois da junção","Caixa de inspeção cheia","Falta de ventilação","Ralo ligado no ramal do vaso","Caimento ruim do ramal","Rede da rua obstruída"],"sis":"Esgoto","fe":"Mola e câmera de inspeção","at":"Antes de quebrar o piso","a":"Abra a caixa de inspeção e passe a mola antes de tudo. A água no ralo é o sinal; a causa está mais à frente."},{"n":33,"c":2,"t":"Ralo ou pia borbulhando depois de escoar","d":"Depois que a água desce, o ralo ou a pia faz ronco, gorgolejo ou solta bolhas de ar.","si":["Ronco depois de escoar a pia","Bolhas subindo no ralo","Cheiro de esgoto depois do ronco","Água do sifão baixa sozinha"],"ca":["Ventilação ausente ou tampada","Obstrução parcial adiante","Sifão sendo sugado","Tubo de queda estreito","Pontos demais no mesmo ramal","Válvula de ar mal instalada"],"sis":"Esgoto","fe":"Lanterna e balde","at":"Antes de quebrar a parede","a":"Confira o telhado e o escoamento antes de abrir parede. Borbulho é falta de ar ou passagem apertada no esgoto."},{"n":34,"c":2,"t":"Ralo da área transborda quando a máquina esvazia","d":"Quando a máquina de lavar solta a água, o ralo ou o tanque não dá vazão e transborda.","si":["Ralo transborda na centrifugação","Espuma saindo pelo ralo","Tanque enche e demora a descer","Fora da máquina escoa normal"],"ca":["Fiapos e sabão no sifão","Tubo de 40 pequeno para a máquina","Espuma travando a caixa","Mangueira mal posicionada","Ralo e tanque na mesma caixa","Tubo adiante obstruído"],"sis":"Esgoto","fe":"Balde e mola fina","at":"Antes de quebrar o piso","a":"Limpe sifão e caixa e assista uma centrifugação inteira. Muitas vezes é fiapo e sabão, não tubo quebrado."},{"n":35,"c":2,"t":"Caixa de inspeção transbordando no quintal","d":"A caixa de inspeção do quintal enche e o esgoto sai pela tampa ou pelas bordas.","si":["Esgoto saindo pela tampa","Cheiro forte no quintal","Ralos da casa escoando devagar","Piora quando todos usam água"],"ca":["Saída da caixa obstruída","Gordura vinda da cozinha","Raiz entrando no tubo","Rede pública cheia","Terra e entulho na caixa","Tubo abatido ou quebrado"],"sis":"Esgoto","fe":"Mola longa e luva","at":"Antes de quebrar o piso","a":"Abra caixa por caixa até a rua. A caixa vazia depois da cheia mostra exatamente o trecho entupido."},{"n":36,"c":2,"t":"Esgoto voltando pelo ponto mais baixo da casa","d":"O esgoto sobe pelo ralo ou pelo vaso mais baixo da casa, mesmo sem uso naquele ponto.","si":["Esgoto sai no ralo mais baixo","Acontece com chuva forte","Vaso do térreo enche sozinho","Caixas do quintal cheias"],"ca":["Ramal predial obstruído","Rede pública cheia","Casa abaixo do nível da rua","Falta de válvula de retenção","Chuva ligada no esgoto","Caixa de inspeção entupida"],"sis":"Esgoto","fe":"Mola longa e câmera","at":"Antes de quebrar o piso","a":"Confira a última caixa e a rede da rua primeiro. Quando a rua está cheia, quebrar dentro de casa não resolve."},{"n":37,"c":2,"t":"Entupimento que volta dias depois de desentupir","d":"O ponto foi desentupido, funcionou por poucos dias e entupiu de novo no mesmo lugar.","si":["Entope sempre no mesmo ponto","Mola libera, mas volta logo","Cliente já chamou outros","Sai pouco material na mola"],"ca":["Gordura que a mola não tirou","Caimento ruim ou barriga","Objeto preso no tubo","Raiz entrando pela junta","Tubo quebrado ou abatido","Redução de diâmetro no trecho"],"sis":"Esgoto","fe":"Câmera de inspeção","at":"Antes de quebrar o piso","a":"Entupimento que volta tem causa fixa. Passe câmera e meça a distância: abra só onde o defeito aparece."},{"n":38,"c":2,"t":"Mau cheiro de esgoto no quintal ou na garagem","d":"Cheiro de esgoto no quintal ou na garagem, sem nada transbordando à vista.","si":["Cheiro forte perto das caixas","Piora em dia quente ou após chuva","Ralo do quintal cheirando","Terra úmida e escura num ponto"],"ca":["Tampa da caixa sem vedação","Ralo seco ligado no esgoto","Caixa de gordura cheia","Tubo enterrado trincado","Fossa ou sumidouro cheio","Ventilação saindo baixa"],"sis":"Esgoto","fe":"Lanterna e balde","at":"Antes de quebrar o piso","a":"Cheiro no quintal costuma vir de tampa, ralo seco ou caixa cheia. Teste isso antes de abrir o piso."},{"n":39,"c":2,"t":"Fossa enchendo rápido demais","d":"A fossa foi esgotada há pouco tempo e já está cheia ou transbordando de novo.","si":["Fossa cheia logo após esgotar","Vasos e ralos lentos","Cheiro forte no terreno","Piora em época de chuva"],"ca":["Sumidouro saturado","Água de chuva entrando","Lençol de água alto","Consumo maior que o projeto","Limpeza atrasada","Vazamento de água para a fossa"],"sis":"Esgoto","fe":"Hidrômetro e lanterna","at":"Antes de quebrar o piso","a":"Teste o hidrômetro e procure chuva entrando antes de condenar a fossa. Às vezes é água limpa enchendo tudo."},{"n":40,"c":2,"t":"Quintal alaga e o ralo não dá vazão na chuva","d":"Em chuva forte a água acumula no quintal ou na garagem porque o ralo não dá conta.","si":["Água empoça na chuva forte","Ralo do quintal transborda","Água entra pela porta da casa","Escoa só depois da chuva"],"ca":["Folhas e terra no ralo","Tubo de chuva obstruído","Saída na sarjeta tampada","Calha caindo no mesmo ralo","Ralo pequeno para a área","Caimento do piso errado"],"sis":"Água de chuva","fe":"Mangueira e mola","at":"Antes de quebrar o piso","a":"Limpe ralo, tubo e saída na sarjeta e teste com mangueira. Nunca ligue a água de chuva no esgoto."},{"n":41,"c":2,"t":"Pia do banheiro escoando devagar","d":"A água do lavatório demora a descer e fica parada na cuba depois de escovar os dentes.","si":["Água parada na cuba","Desce devagar e com ronco","Cheiro ruim na pia","Tampa da válvula travando"],"ca":["Cabelo e sabão na válvula","Sifão sujo","Válvula clic-clac emperrada","Ladrão da cuba entupido","Tubo da parede obstruído","Falta de ventilação"],"sis":"Esgoto","fe":"Balde e gancho de cabelo","at":"Antes de trocar a peça","a":"Limpe a haste da válvula e o sifão antes de trocar qualquer peça. Na maioria das vezes é cabelo e sabão."},{"n":42,"c":2,"t":"Barata ou rato saindo pelo ralo","d":"Aparecem baratas ou ratos saindo pelo ralo ou pela caixa de inspeção da casa.","si":["Baratas saindo à noite pelo ralo","Grelha deslocada ou roída","Cheiro de esgoto junto","Ralo pouco usado"],"ca":["Ralo com fecho hídrico seco","Grelha solta ou sem fecho","Ralo seco ligado no esgoto","Tampa da caixa quebrada","Tubo de esgoto rachado","Caixa sifonada sem vedação"],"sis":"Esgoto","fe":"Lanterna e balde","at":"Antes de quebrar o piso","a":"Ralo com água no sifão e grelha com fecho resolvem boa parte dos casos. Abra o piso só se a câmera mostrar trinca."},{"n":43,"c":2,"t":"Cheiro de esgoto na base do vaso","d":"O cheiro de esgoto vem do pé do vaso sanitário, mesmo com o vaso limpo e sem entupir.","si":["Cheiro forte no pé do vaso","Rejunte escuro em volta da louça","Vaso mexe um pouco ao sentar","Piora depois da descarga"],"ca":["Anel de vedação ressecado","Vaso solto no piso","Tubo de 100 abaixo do piso","Rejunte da base sujo","Fecho hídrico do vaso baixo","Trinca na louça"],"sis":"Esgoto","fe":"Lanterna e chave de boca","at":"Antes de quebrar o piso","a":"Cheiro no pé do vaso costuma ser o anel ou o vaso solto. Retire e reassente antes de mexer no tubo."},{"n":44,"c":2,"t":"Entupimento logo depois de obra ou reforma","d":"Pouco depois da obra ou da reforma, ralos, pias ou o vaso começaram a entupir.","si":["Começou depois da reforma","Resíduo branco ou cinza no ralo","Mola bate em algo duro","Vários pontos escoando mal"],"ca":["Argamassa ou rejunte no ralo","Gesso assentado no tubo","Entulho na caixa de inspeção","Tubo amassado no contrapiso","Conexão invertida ou errada","Tinta ou massa no ralo"],"sis":"Esgoto","fe":"Mola e câmera de inspeção","at":"Antes de quebrar o piso","a":"Limpe caixas e passe a câmera antes de quebrar o piso novo. O vídeo mostra se é resto de obra ou tubo danificado."},{"n":45,"c":2,"t":"Esgoto minando no piso ou na parede","d":"Mancha escura e cheiro de esgoto saindo pelo piso, rodapé ou parede, sem transbordar ralo.","si":["Mancha escura com cheiro","Rejunte úmido perto do ralo","Piora quando usam o banheiro","Mosquitinho perto da mancha"],"ca":["Junta de anel mal encaixada","Conexão sem cola ou solta","Tubo trincado","Caixa sifonada trincada","Entupimento forçando a junta","Tubo de queda furado"],"sis":"Esgoto","fe":"Corante e câmera","at":"Antes de quebrar a parede","a":"Use corante ponto a ponto antes de abrir. Assim você quebra só o trajeto que realmente vaza."},{"n":46,"c":3,"t":"Torneira pingando mesmo bem fechada","d":"A bica continua pingando depois de fechada, e apertar mais o volante não resolve.","si":["Pinga com o volante bem fechado","Apertar mais não resolve","Volante cada vez mais duro","Marca de calcário na cuba"],"ca":["Vedante (courinho) gasto","Reparo de 1/4 de volta gasto","Sujeira presa na vedação","Sede da torneira gasta","Castelo frouxo ou gasto","Pressão alta na rede"],"sis":"Água fria","fe":"Chave de boca e reparo","at":"Antes de trocar a peça","a":"Torneira pingando quase sempre pede só vedante ou reparo. Troque a torneira só se a sede estiver condenada."},{"n":47,"c":3,"t":"Torneira da cozinha com pouca água e o resto normal","d":"Só um ponto sai fraco; o chuveiro e as outras torneiras estão com a pressão de sempre.","si":["Jato fraco só na cozinha","Resto da casa com pressão normal","Piorou aos poucos ou de repente","Às vezes espirra ou sai ar"],"ca":["Arejador entupido","Registro do ponto meio fechado","Flexível dobrado ou obstruído","Cozinha ligada direto na rua","Reparo ou cartucho sujo","Tubo do ponto obstruído"],"sis":"Água fria","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Tire o arejador antes de tudo: é o teste mais rápido e resolve boa parte dos casos de jato fraco."},{"n":48,"c":3,"t":"Torneira vazando pela base ou pelo corpo","d":"A água escorre pela base da torneira ou pela junta da bica móvel quando ela está aberta.","si":["Água acumulando na base","Vaza mais com a torneira aberta","Junta da bica móvel pingando","Bancada sempre molhada"],"ca":["Anel o-ring da bica gasto","Torneira frouxa na bancada","Anel da base ressecado","Cartucho ou castelo vazando","Engate ou rosca de entrada","Corpo da torneira trincado"],"sis":"Água fria","fe":"Chave e jogo de anéis","at":"Antes de trocar a peça","a":"Seque, abra e observe de onde a água brota. Muitas vezes é só o anel da bica, não a torneira toda."},{"n":49,"c":3,"t":"Registro vazando pelo volante quando abre","d":"Com o registro aberto, a água escorre pela haste, pelo volante ou por trás da canopla.","si":["Água escorre pelo volante aberto","Fechado, não vaza","Canopla com marca de água","Azulejo molhado embaixo"],"ca":["Gaxeta ou anel da haste gasto","Porca do castelo frouxa","Castelo gasto ou mal vedado","Haste riscada ou corroída","Vedação ressecada no quente","Corpo do registro trincado"],"sis":"Água fria e quente","fe":"Chave de boca","at":"Antes de quebrar a parede","a":"Vazamento pelo volante se resolve por fora, com anel ou castelo. Só abra a parede se o corpo estiver vazando."},{"n":50,"c":3,"t":"Fecha o registro e a água continua passando","d":"O registro gira até o fim, mas a água continua saindo nos pontos depois dele.","si":["Registro fecha até o fim","Pontos continuam com água","Filete fraco que não para","Não dá para trocar um reparo"],"ca":["Gaveta gasta ou corroída","Sujeira presa na gaveta","Haste espanada","Ponto alimentado por outro ramal","Água residual nos tubos","Sede do corpo danificada"],"sis":"Água fria","fe":"Chave de boca e lanterna","at":"Antes de trocar a peça","a":"Espere o tubo esvaziar antes de condenar o registro: o filete dos primeiros minutos é normal."},{"n":51,"c":3,"t":"Registro duro, travado ou girando em falso","d":"O volante não gira, gira muito pesado ou roda solto sem abrir nem fechar a água.","si":["Volante muito pesado","Gira solto sem efeito","Registro parado há anos","Volante com estrias gastas"],"ca":["Calcário por falta de uso","Volante espanado","Haste espanada no castelo","Gaxeta apertada demais","Castelo danificado por força","Gaveta presa no corpo"],"sis":"Água fria e quente","fe":"Chave e graxa de silicone","at":"Antes de trocar a peça","a":"Não force o volante com chave de grifo: a haste quebra e um simples ajuste vira troca de registro."},{"n":52,"c":3,"t":"Monocomando só sai quente ou só fria","d":"Girando a alavanca para o outro lado, a temperatura da água quase não muda.","si":["Só sai quente ou só fria","Alavanca gira sem misturar","Pouca vazão de um dos lados","Começou após falta de água"],"ca":["Registro de um lado fechado","Filtro de entrada entupido","Cartucho misturador gasto","Pressões diferentes nas entradas","Flexível dobrado de um lado","Aquecedor sem aquecer"],"sis":"Água fria e quente","fe":"Chave Allen e termômetro","at":"Antes de trocar a peça","a":"Antes de trocar o misturador, compare a vazão dos dois flexíveis. O defeito costuma estar antes dele."},{"n":53,"c":3,"t":"Água quente aparecendo na torneira fria","d":"Abre-se a torneira ou o lado frio e a água sai morna, mesmo longe do aquecedor.","si":["Lado frio saindo morno","Piora depois de usar o chuveiro","Acontece em mais de um ponto","Esfria depois de um tempo aberta"],"ca":["Misturador cruzando as águas","Quente com mais pressão que a fria","Falta de válvula de retenção","Ducha higiênica misturadora","Tubo frio encostado no quente","Ligação cruzada na obra"],"sis":"Água fria e quente","fe":"Termômetro e chave","at":"Antes de trocar a peça","a":"Feche um misturador por vez antes de trocar peças: um único cartucho pode esquentar a fria da casa toda."},{"n":54,"c":3,"t":"Torneira espirrando ou com jato torto","d":"O jato sai para o lado, aberto em leque ou espirrando para fora da cuba.","si":["Jato torto ou em leque","Água espirra fora da cuba","Jato cospe ar de vez em quando","Ponta da bica com calcário"],"ca":["Arejador sujo com calcário","Arejador torto ou mal rosqueado","Ar na tubulação","Arejador errado para a bica","Pressão alta no ponto","Bica amassada ou com rebarba"],"sis":"Água fria","fe":"Alicate e vinagre","at":"Antes de trocar a peça","a":"Tire o arejador e teste antes de tudo: jato torto quase sempre é calcário na ponta, não a torneira."},{"n":55,"c":3,"t":"Torneira elétrica não esquenta","d":"A água sai com pressão normal, mas fria, mesmo com o seletor na posição quente.","si":["Água fria em qualquer posição","Sem chiado de aquecimento","Parou depois de faltar água","Disjuntor ligado"],"ca":["Resistência queimada","Pressão baixa não aciona","Disjuntor ou fiação sem energia","Seletor na posição fria","Vazão alta demais","Diafragma ou contatos gastos"],"sis":"Água fria e elétrica","fe":"Multímetro","at":"Antes de trocar a peça","a":"Teste o estalo e a vazão antes de comprar resistência: com pouca pressão, a peça nova também não aquece."},{"n":56,"c":3,"t":"Torneira do tanque ou jardim vazando na parede","d":"Água escorre pela parede em volta da torneira, ou a torneira gira solta na rosca.","si":["Água escorre pela parede","Torneira gira ou ficou torta","Mancha embaixo da torneira","Reboco solto em volta"],"ca":["Vedação da rosca vencida","Bucha de latão girou no joelho","Rosca da torneira espanada","Joelho trincado pelo aperto","Torneira vazando pelo corpo","Tubo embutido trincado"],"sis":"Água fria","fe":"Fita veda rosca e chave","at":"Antes de quebrar a parede","a":"Retire a torneira e olhe a rosca antes de quebrar. Muitas vezes é só a vedação ou a bucha que girou."},{"n":57,"c":3,"t":"Chuveiro pingando com o registro fechado","d":"O registro está fechado, mas o chuveiro continua pingando ou soltando um filete.","si":["Pingo constante no chuveiro","Registro bem fechado","Apertar mais não resolve","Box sempre molhado"],"ca":["Vedante do registro gasto","Água residual do chuveiro","Reparo de 1/4 de volta gasto","Sujeira presa na vedação","Cartucho do misturador","Sede do registro gasta"],"sis":"Água fria e quente","fe":"Chave de boca e reparo","at":"Antes de trocar a peça","a":"Espere 10 minutos antes de condenar o registro: o chuveiro pinga um pouco até esvaziar e isso é normal."},{"n":58,"c":3,"t":"Engate flexível com bolha ou estourado","d":"O flexível da pia ou do vaso estufou numa bolha ou rompeu e alagou o cômodo.","si":["Bolha na malha do flexível","Malha enferrujada ou desfiada","Flexível estourou e alagou","Pingo na porca do engate"],"ca":["Flexível velho ou ressecado","Pressão alta da rua","Torção ou dobra na instalação","Flexível de baixa pressão","Malha corroída por produto","Golpe de aríete"],"sis":"Água fria","fe":"Chave de boca e manômetro","at":"Antes de trocar a peça","a":"Troque o flexível, mas meça a pressão: se ela estiver alta, o novo estoura do mesmo jeito."},{"n":59,"c":3,"t":"Fecha o registro geral e ainda sai água","d":"O cliente fecha o registro do cavalete e as torneiras continuam com água normal.","si":["Cavalete fechado, água saindo","Não consegue fazer um reparo","Pressão continua igual","Só alguns pontos param"],"ca":["Casa alimentada pela caixa-d'água","Registro do barrilete aberto","Registro do cavalete não veda","Bomba ou pressurizador ligado","Água residual nos tubos","Ramal de outra origem"],"sis":"Água fria","fe":"Lanterna e chave","at":"Antes de trocar a peça","a":"Não condene o registro geral: em casa com caixa-d'água, ele só corta a rua. Feche também a saída da caixa."},{"n":60,"c":3,"t":"Torneira nova com pouca água","d":"Torneira ou misturador recém-instalado sai fraco, enquanto o modelo antigo saía bem.","si":["Peça nova mais fraca que a antiga","Resto da casa normal","Casa abastecida por caixa-d'água","Jato fino mesmo todo aberto"],"ca":["Modelo para alta pressão","Restritor ou arejador econômico","Sujeira da obra no filtro","Flexível fino ou estrangulado","Registro do ponto meio aberto","Cartucho com defeito de fábrica"],"sis":"Água fria","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Leia a pressão mínima na embalagem: torneira de alta pressão em casa de caixa-d'água sai fraca mesmo nova."},{"n":61,"c":4,"t":"Caixa acoplada enchendo sem parar","d":"Barulho de água entrando na caixa o tempo todo, mesmo sem ninguém dar descarga.","si":["Chiado de água entrando na caixa","Filete escorrendo no fundo do vaso","Conta de água mais alta","Caixa recarrega sozinha"],"ca":["Vedante da descarga gasto","Boia desregulada, nível alto","Sujeira na sede do vedante","Corrente ou haste presa","Válvula de entrada não fecha","Tubo ladrão trincado"],"sis":"Água fria","fe":"Corante e lanterna","at":"Antes de trocar a peça","a":"Não troque o mecanismo inteiro antes do corante e da boia: muitas vezes é só regular ou limpar."},{"n":62,"c":4,"t":"Filete de água no vaso com válvula de parede","d":"Depois da descarga, um filete fino continua descendo pela louça, sem parar.","si":["Filete fino descendo na louça","Sem caixa e sem chiado","Conta de água mais alta","Mancha de calcário no vaso"],"ca":["Reparo da válvula gasto","Regulagem de fechamento errada","Sujeira no reparo","Sede da válvula marcada","Botão de acionamento preso","Pressão fora da faixa da válvula"],"sis":"Água fria","fe":"Papel seco e chave","at":"Antes de quebrar a parede","a":"A base da válvula fica embutida. Limpe, regule e troque o reparo antes de abrir a parede."},{"n":63,"c":4,"t":"Válvula de descarga disparada, jorrando sem parar","d":"Apertou a descarga e a água não para de jorrar com força dentro do vaso.","si":["Jato forte sem parar no vaso","Começou ao apertar a descarga","Caixa-d'água esvaziando","Botão afundado ou solto"],"ca":["Sujeira travando o pistão","Reparo quebrado ou gasto","Botão preso no acionamento","Regulagem de tempo aberta demais","Ar na tubulação","Válvula incompatível com a pressão"],"sis":"Água fria","fe":"Chave de fenda e reparo","at":"Antes de trocar a peça","a":"Disparo depois de falta de água costuma ser sujeira no pistão: lave o reparo antes de comprar outro."},{"n":64,"c":4,"t":"Descarga fraca, não leva os dejetos","d":"A descarga funciona, mas a água entra fraca e os dejetos ficam no vaso.","si":["Precisa dar duas descargas","Água entra fraca na louça","Dejeto volta a boiar","Nível do vaso desce devagar"],"ca":["Nível baixo na caixa acoplada","Furos do rebordo com calcário","Válvula de parede sem vazão","Entupimento parcial no ramal","Válvula regulada fechada","Falta de ventilação no esgoto"],"sis":"Água fria e esgoto","fe":"Balde e espelho","at":"Antes de trocar a peça","a":"Faça o teste do balde: se ele leva tudo, o vaso está bom e o problema é a água da descarga."},{"n":65,"c":4,"t":"Caixa acoplada demora ou não enche","d":"Depois da descarga, a caixa leva muitos minutos para encher ou fica vazia.","si":["Caixa leva minutos para encher","Às vezes não enche nada","Chiado fraco de entrada","Resto da casa com água"],"ca":["Filtro de entrada entupido","Registro do vaso meio fechado","Boia travada ou presa","Flexível dobrado ou obstruído","Válvula de entrada com defeito","Pressão baixa no ramal"],"sis":"Água fria","fe":"Chave e balde","at":"Antes de trocar a peça","a":"Limpe o filtro da entrada antes de trocar o mecanismo: depois de falta de água ele entope com areia."},{"n":66,"c":4,"t":"Água no piso em volta do pé do vaso","d":"Aparece água ou mancha no piso junto à base do vaso, sem saber de onde vem.","si":["Poça junto à base do vaso","Rejunte escuro em volta","Piora depois da descarga","Cheiro na base do vaso"],"ca":["Anel de vedação gasto ou torto","Flexível ou registro pingando","Junção da caixa com a bacia","Vaso solto no piso","Condensação na louça","Trinca na louça"],"sis":"Água fria e esgoto","fe":"Papel toalha e corante","at":"Antes de quebrar o piso","a":"Teste flexível, junção e anel antes de abrir o piso: muitas vezes o vazamento está no próprio vaso."},{"n":67,"c":4,"t":"Caixa acoplada vazando na junção com a bacia","d":"Pinga água entre a caixa e a bacia, principalmente logo depois da descarga.","si":["Pingo entre caixa e bacia","Piora logo após a descarga","Parafusos com ferrugem","Caixa balança na bacia"],"ca":["Junta entre caixa e bacia gasta","Parafusos da caixa frouxos","Arruelas dos parafusos gastas","Porca do mecanismo de saída","Flexível escorrendo à junção","Louça trincada"],"sis":"Água fria","fe":"Chave de boca e lanterna","at":"Antes de trocar a peça","a":"Aperto demais trinca a louça. Troque junta e arruelas e aperte aos poucos antes de condenar o vaso."},{"n":68,"c":4,"t":"Botão ou alavanca não aciona a descarga","d":"Aperta-se o botão ou a alavanca e nada acontece, mesmo com a caixa cheia.","si":["Botão afunda e não solta água","Caixa cheia de água","Alavanca solta ou leve demais","Às vezes funciona, às vezes não"],"ca":["Corrente solta ou partida","Haste do botão quebrada","Botão desencaixado","Haste curta ou desregulada","Mecanismo de saída quebrado","Alavanca com eixo quebrado"],"sis":"Água fria","fe":"Chave de fenda e alicate","at":"Antes de trocar a peça","a":"Acione com a mão dentro da caixa antes de comprar peça: muitas vezes é só corrente ou haste solta."},{"n":69,"c":4,"t":"Válvula de parede vazando pelo botão","d":"Escorre água pelo acabamento da válvula na parede, durante ou depois da descarga.","si":["Água escorre pelo botão","Piora ao dar descarga","Azulejo molhado embaixo","Mancha na parede do outro lado"],"ca":["Vedação do acionamento gasta","Reparo da válvula com defeito","Acabamento mal instalado","Registro integrado vazando","Prolongador mal ajustado","Base da válvula trincada"],"sis":"Água fria","fe":"Chave de fenda e reparo","at":"Antes de quebrar a parede","a":"Troque anel, acionamento e reparo antes de abrir: a base embutida é a última suspeita, não a primeira."},{"n":70,"c":4,"t":"Água do fundo do vaso baixando sozinha","d":"O nível da água parada no fundo do vaso baixa sozinho, às vezes até quase sumir.","si":["Nível do vaso abaixo do normal","Cheiro de esgoto no banheiro","Água do vaso balança","Baixa quando usam outro ponto"],"ca":["Falta de ventilação no esgoto","Papel ou fiapo puxando a água","Entupimento parcial adiante","Vento no tubo de ventilação","Evaporação em vaso sem uso","Trinca na louça do sifão"],"sis":"Esgoto","fe":"Lanterna e balde","at":"Antes de trocar a peça","a":"Não troque o vaso por causa do nível baixo: o defeito costuma estar na ventilação do esgoto, não na louça."},{"n":71,"c":4,"t":"Descarga dupla: só um botão funciona","d":"Um dos dois botões da caixa acoplada não solta água ou solta pouco demais.","si":["Um botão afunda sem efeito","O outro botão funciona normal","Meia descarga fraca demais","Botão volta devagar"],"ca":["Haste do botão desregulada","Botão desencaixado","Peça do acionamento quebrada","Meia descarga regulada baixa","Sujeira no mecanismo de saída","Mecanismo de saída gasto"],"sis":"Água fria","fe":"Chave de fenda e lanterna","at":"Antes de trocar a peça","a":"Antes de trocar o mecanismo, acione com a mão: muitas vezes é só a altura da haste do botão."},{"n":72,"c":4,"t":"Vaso balançando ou solto no piso","d":"O vaso mexe quando a pessoa senta e pode estar vazando ou soltando cheiro na base.","si":["Vaso mexe ao sentar","Rejunte da base rachado","Cheiro na base do vaso","Mancha no piso em volta"],"ca":["Parafusos ou buchas soltos","Piso desnivelado","Anel de vedação esmagado","Rejunte da base quebrado","Tubo de esgoto alto no piso","Louça trincada na base"],"sis":"Esgoto","fe":"Chave de boca e nível","at":"Antes de trocar a peça","a":"Aperte e calce antes de trocar o vaso. Mas vaso que balançou muito pede anel novo, ou volta a vazar."},{"n":73,"c":4,"t":"Caixa de descarga externa escorrendo no vaso","d":"A caixa alta de plástico, de cordinha ou alavanca, deixa um filete descer ao vaso.","si":["Filete descendo no vaso","Chiado de caixa enchendo","Cordinha volta devagar","Caixa recarrega sozinha"],"ca":["Obturador ou sino gasto","Boia desregulada","Cordinha ou alavanca presa","Sujeira no assento","Vedação da boia gasta","Caixa trincada"],"sis":"Água fria","fe":"Corante e chave de boca","at":"Antes de trocar a peça","a":"Caixa externa é simples: boia, cordinha e obturador resolvem a maioria dos casos antes de trocar a caixa."},{"n":74,"c":4,"t":"Ducha higiênica pingando ou vazando","d":"A ducha ao lado do vaso pinga pelo bico, vaza na mangueira ou no registro.","si":["Bico da ducha pingando","Mangueira estufada ou molhada","Registro da ducha vazando","Piso molhado ao lado do vaso"],"ca":["Ducha deixada pressurizada","Vedação do gatilho gasta","Registro da ducha passando","Mangueira ou rosca vazando","Pressão alta no ponto","Misturador cruzando as águas"],"sis":"Água fria e quente","fe":"Chave de boca e fita","at":"Antes de trocar a peça","a":"Ducha deixada com o registro aberto estoura a mangueira e gasta o gatilho. Oriente o cliente antes de trocar."},{"n":75,"c":4,"t":"Vaso novo com descarga ruim ou vazando","d":"O vaso acabou de ser instalado e a descarga é fraca, entope ou vaza na base.","si":["Descarga fraca desde a instalação","Água no pé do vaso","Vaso torto ou balançando","Caixa enchendo pouco"],"ca":["Anel de vedação errado ou torto","Distância da saída incompatível","Nível da caixa abaixo da marca","Mecanismo mal montado","Vaso fora de nível","Sobra de obra no esgoto"],"sis":"Água fria e esgoto","fe":"Trena e nível","at":"Antes de trocar a peça","a":"Vaso novo raramente vem com defeito: confira nível, anel, medida da saída e caixa antes de devolver."},{"n":76,"c":5,"t":"Chuveiro fraco e o resto da casa normal","d":"Só o chuveiro sai fraco; as torneiras e os outros pontos estão com a pressão de sempre.","si":["Jato fraco só no chuveiro","Furinhos do espalhador falhando","Resto da casa com pressão normal","Piorou aos poucos com o tempo"],"ca":["Espalhador com calcário","Registro de pressão meio fechado","Filtro da entrada entupido","Chuveiro pede mais pressão","Tubo do chuveiro obstruído","Ramal fino ou com muitas curvas"],"sis":"Água fria e quente","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Tire o espalhador e limpe o filtro da entrada antes de condenar o chuveiro ou o registro."},{"n":77,"c":5,"t":"Pouca pressão na casa inteira","d":"Todos os pontos saem fracos, do chuveiro à torneira, inclusive os que vêm da caixa.","si":["Todos os pontos saem fracos","Chuveiro e torneiras sem força","Caixa-d'água baixa ou vazia","Pior nos pontos mais altos"],"ca":["Caixa-d'água baixa demais","Registro geral meio fechado","Caixa vazia ou enchendo pouco","Tubulação fina demais","Cano galvanizado obstruído","Pressão baixa da rede pública"],"sis":"Água fria","fe":"Manômetro e trena","at":"Antes de trocar a peça","a":"Confira o registro da caixa e a altura antes de vender pressurizador ou trocar a tubulação."},{"n":78,"c":5,"t":"Chuveiro elétrico não esquenta","d":"Sai água, mas fria em todas as posições do seletor de temperatura.","si":["Água fria nas duas posições","Parou de esquentar de repente","Seletor mudado sem efeito","Disjuntor ligado no quadro"],"ca":["Resistência queimada","Pressão baixa não liga o contato","Seletor na posição frio","Disjuntor desarmado","Mau contato na ligação","Diafragma furado ou travado"],"sis":"Elétrico e água","fe":"Multímetro (sem energia)","at":"Antes de trocar a peça","a":"Confira seletor, registro e disjuntor antes de trocar o chuveiro: muitas vezes basta trocar a resistência."},{"n":79,"c":5,"t":"Chuveiro queimando a resistência toda hora","d":"A resistência nova dura dias ou semanas e queima de novo, às vezes no primeiro banho.","si":["Resistência nova queima rápido","Estalo ou cheiro ao ligar","Às vezes sai ar no chuveiro","Água muito quente antes de queimar"],"ca":["Ligado sem água ou com ar","Resistência de tensão errada","Vazão baixa demais","Resistência mal montada","Mau contato nos bornes","Chuveiro velho ou deformado"],"sis":"Elétrico e água","fe":"Multímetro (sem energia)","at":"Antes de trocar a peça","a":"Não troque a 3ª resistência sem achar a causa: ar na linha, tensão errada ou vazão baixa queimam a próxima."},{"n":80,"c":5,"t":"Chuveiro dando choque","d":"Sente formigamento ou choque ao encostar no chuveiro, no registro ou na água do banho.","si":["Formigamento ao tocar na água","Choque no registro de metal","Pior com o pé descalço","Chuveiro antigo ou úmido"],"ca":["Chuveiro sem aterramento","Fio desencapado encostando","Umidade na ligação elétrica","Resistência deformada","Chuveiro velho com fuga","Circuito sem DR ou proteção"],"sis":"Elétrico e água","fe":"Multímetro (sem energia)","at":"Antes de trocar a peça","a":"Choque é risco de vida: não troque só o chuveiro e libere o banho. Sem terra e sem DR, o risco continua."},{"n":81,"c":5,"t":"Chuveiro esquenta pouco, água só morna","d":"Esquenta, mas só fica morno no inverno ou quando o registro é aberto um pouco mais.","si":["Água morna na posição inverno","Esquenta mais com pouca água","Piorou ao trocar o chuveiro","Pior nos dias frios"],"ca":["Vazão alta para a potência","Resistência de potência menor","Chuveiro de potência baixa","Tensão baixa no ponto","Seletor ou contato gasto","Resistência de 220 V em 127 V"],"sis":"Elétrico e água","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Feche um pouco o registro antes de trocar o chuveiro: muita água para pouca potência só sai morna."},{"n":82,"c":5,"t":"Água do chuveiro alterna entre quente e fria","d":"No meio do banho a água esfria e volta a esquentar, com aquecedor a gás de passagem.","si":["Esfria e esquenta no mesmo banho","Aquecedor apaga e reacende","Pior com outro ponto aberto","Pior com o registro pouco aberto"],"ca":["Vazão no limite mínimo","Outro ponto aberto junto","Pressão da caixa oscilando","Misturador desbalanceado","Filtro de entrada sujo","Ar ou falha no aquecedor"],"sis":"Água quente a gás","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Antes de condenar o aquecedor, teste a vazão: abaixo do mínimo ele apaga e reacende sozinho."},{"n":83,"c":5,"t":"Aquecedor a gás não acende ao abrir o chuveiro","d":"Abre o chuveiro e o aquecedor não liga, ou estala e não acende a chama.","si":["Água sai só fria","Aquecedor estala sem acender","Visor sem chama","Acende só com tudo aberto"],"ca":["Pilhas fracas da ignição","Vazão abaixo do mínimo","Filtro de entrada entupido","Gás fechado ou botijão vazio","Sensor de fluxo travado","Falha interna do aquecedor"],"sis":"Água quente a gás","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Pilha, filtro e vazão primeiro: são causas comuns e baratas. Na parte de gás, só técnico habilitado."},{"n":84,"c":5,"t":"Água quente demora muito para chegar","d":"Abre a torneira ou o chuveiro e escorre água fria por muito tempo até chegar a quente.","si":["Muita água fria antes da quente","Pior no ponto mais distante","Pior de manhã ou no frio","Desperdício de água no banho"],"ca":["Ponto longe do aquecedor","Tubo sem isolamento térmico","Tubo de diâmetro grande demais","Vazão baixa no ponto","Falta de recirculação","Aquecedor lento para responder"],"sis":"Água quente","fe":"Balde e cronômetro","at":"Antes de quebrar a parede","a":"Cronometre e compare os pontos antes de abrir parede: muitas vezes é só distância, sem defeito a consertar."},{"n":85,"c":5,"t":"Chuveiro vazando na conexão do cano ou na carcaça","d":"Escorre água pela parede na ligação do chuveiro ou pinga pela própria carcaça.","si":["Água escorrendo pela parede","Pinga pela carcaça do chuveiro","Mancha atrás do chuveiro","Vaza só com o chuveiro aberto"],"ca":["Rosca do braço sem vedação","Chuveiro mal rosqueado","Braço solto na parede","Carcaça trincada","Vedação interna gasta","Joelho da parede vazando"],"sis":"Água fria e elétrico","fe":"Fita veda rosca","at":"Antes de quebrar a parede","a":"Seque e observe com o chuveiro aberto: muitas vezes é a rosca do braço, que se resolve sem abrir a parede."},{"n":86,"c":5,"t":"Pressão boa de manhã e fraca à tarde","d":"Cedo a água sai forte; ao longo do dia vai enfraquecendo até quase parar à tarde.","si":["Forte de manhã, fraca à tarde","Caixa baixando durante o dia","Volta ao normal de madrugada","Pior em dias de calor"],"ca":["Caixa esvaziando no dia","Pressão da rua cai à tarde","Boia demorando a repor","Pontos ligados direto na rua","Caixa pequena para a casa","Vazamento esvaziando a caixa"],"sis":"Água fria","fe":"Manômetro","at":"Antes de trocar a peça","a":"Anote o nível da caixa de manhã e à tarde antes de vender bomba: muitas vezes o problema é a rua ou a reserva."},{"n":87,"c":5,"t":"Abre outra torneira e o chuveiro enfraquece","d":"No meio do banho, alguém abre a pia ou dá descarga e o chuveiro perde força ou esfria.","si":["Perde força com outro ponto aberto","Esfria quando dão descarga","Volta ao normal ao fechar","Pior com 2 banheiros em uso"],"ca":["Ramal compartilhado fino","Descarga na mesma coluna","Pouca altura da caixa","Quente e fria desbalanceadas","Aquecedor no limite de vazão","Registro ou tubo estrangulado"],"sis":"Água fria e quente","fe":"Balde e cronômetro","at":"Antes de quebrar a parede","a":"Teste ponto por ponto antes de abrir parede: saber qual ponto derruba o chuveiro mostra qual coluna mexer."},{"n":88,"c":5,"t":"Aquecedor solar não esquenta a água","d":"Mesmo com sol forte, a água do reservatório térmico fica fria ou só morna.","si":["Água fria mesmo com sol","Placas quentes, boiler frio","Só esquenta com a resistência","Piorou após mexerem no telhado"],"ca":["Placas sujas ou com sombra","Ar no circuito das placas","Misturador puxando fria","Boiler abaixo do topo das placas","Resistência ou termostato","Placa vazando ou obstruída"],"sis":"Água quente solar","fe":"Termômetro","at":"Antes de trocar a peça","a":"Limpe as placas e meça a água do boiler antes de condenar o sistema: costuma ser sujeira, ar ou misturador."},{"n":89,"c":5,"t":"Pressão alta demais, espirra e faz barulho","d":"A água sai com força exagerada, espirra na pia e os canos batem ou chiam.","si":["Torneira espirra na bancada","Canos batem ao fechar","Flexíveis estufando","Reparos gastam rápido"],"ca":["Ponto ligado direto na rua","Prédio sem válvula redutora","Válvula redutora com defeito","Pressurizador regulado alto","Torneira sem arejador","Golpe de aríete na rede"],"sis":"Água fria","fe":"Manômetro","at":"Antes de trocar a peça","a":"Meça a pressão antes de trocar reparos e flexíveis: com pressão alta, a peça nova estraga de novo."},{"n":90,"c":5,"t":"Chuveiro com cheiro de queimado ou fio derretido","d":"Cheiro de plástico queimado no banho, fio escurecido ou derretido na ligação do chuveiro.","si":["Cheiro de queimado no banho","Fio ou conector escurecido","Disjuntor quente ou desarmando","Chuveiro esquenta menos"],"ca":["Conector frouxo ou emenda ruim","Fio fino para a potência","Disjuntor maior que o fio","Resistência em curto parcial","Umidade na ligação","Chuveiro mais potente"],"sis":"Elétrico","fe":"Lanterna (sem energia)","at":"Antes de trocar a peça","a":"Trocar só o chuveiro não resolve: se o fio derreteu, conector, fio e disjuntor precisam ser revistos."},{"n":91,"c":6,"t":"Caixa-d'água transbordando pelo ladrão","d":"A água escorre o tempo todo pelo tubo ladrão, mesmo com a caixa já cheia.","si":["Ladrão escorrendo sem parar","Barulho de água entrando","Conta de água mais alta","Água escorrendo no telhado"],"ca":["Boia desregulada","Vedação da boia gasta","Haste torta ou presa","Boia furada ou encharcada","Sujeira na válvula da boia","Pressão alta na entrada"],"sis":"Água fria","fe":"Chave e lanterna","at":"Antes de trocar a peça","a":"Levante a boia com a mão antes de trocar: se a água parar, basta regular o nível."},{"n":92,"c":6,"t":"Caixa-d'água não enche ou enche devagar","d":"A caixa fica baixa ou vazia por dias, mesmo com água chegando no cavalete.","si":["Caixa baixa ou vazia","Pouca água entrando pela boia","Casa sem água à noite","Torneira do cavalete com água"],"ca":["Boia travada fechada","Registro de entrada meio fechado","Pressão da rua insuficiente","Válvula da boia entupida","Ar no tubo de entrada","Tubo de entrada obstruído"],"sis":"Água fria","fe":"Manômetro","at":"Antes de trocar a peça","a":"Baixe a boia com a mão e veja o cavalete antes de vender bomba: muitas vezes a boia só travou."},{"n":93,"c":6,"t":"Caixa-d'água vazando pelo fundo ou na conexão","d":"Escorre água pela lateral ou pelo fundo da caixa, molhando a laje ou o forro.","si":["Laje ou forro molhado","Gotas no adaptador da saída","Mancha embaixo da caixa","Nível baixando sem uso"],"ca":["Adaptador de flange mal vedado","Furo da conexão mal feito","Rosca do adaptador vazando","Caixa trincada","Ladrão ou entrada vazando","Base irregular forçando o fundo"],"sis":"Água fria","fe":"Lanterna e chave","at":"Antes de trocar a peça","a":"Seque e ache a gota antes de condenar a caixa: muitas vezes é só o flange ou a rosca."},{"n":94,"c":6,"t":"Boia batendo ou vibrando ao encher","d":"Enquanto a caixa enche, a boia trepida e faz um barulho que se ouve pela casa.","si":["Barulho de batida ao encher","Canos tremendo na parede","Pior de madrugada","Boia balançando na água"],"ca":["Pressão alta na entrada","Boia de baixa pressão","Haste longa e boia leve","Onda formada na caixa","Tubo de entrada solto","Reparo da boia gasto"],"sis":"Água fria","fe":"Manômetro","at":"Antes de trocar a peça","a":"Feche um pouco o registro de entrada e escute: se o barulho sumir, é pressão, não boia quebrada."},{"n":95,"c":6,"t":"Água da caixa suja, com cheiro ou bicho","d":"A água sai turva, com cheiro, larvas, folhas ou insetos que vêm da caixa-d'água.","si":["Água turva ou com cheiro","Larvas ou insetos na torneira","Lodo no fundo da caixa","Tampa quebrada ou solta"],"ca":["Limpeza atrasada","Tampa solta ou quebrada","Ladrão sem tela","Respiro sem proteção","Água parada por muito tempo","Sujeira vinda da rua"],"sis":"Água potável","fe":"Lanterna e balde","at":"Antes de trocar a peça","a":"Abra a caixa e veja o fundo antes de culpar a rede: tampa solta e limpeza atrasada são as causas mais vistas."},{"n":96,"c":6,"t":"Caixa-d'água esvazia sozinha durante a noite","d":"À noite ninguém usa água, mas de manhã a caixa está bem mais baixa.","si":["Caixa baixa pela manhã","Ninguém usou água à noite","Barulho de água correndo","Conta de água mais alta"],"ca":["Descarga passando água ao vaso","Torneira ou chuveiro pingando","Vazamento em tubo depois da caixa","Conexão da caixa vazando","Retorno pela bomba de recalque","Caixa trincada"],"sis":"Água fria","fe":"Corante e trena","at":"Antes de quebrar a parede","a":"Feche a saída da caixa por uma noite antes de abrir parede: o teste separa caixa, descarga e tubo."},{"n":97,"c":6,"t":"Depois de lavar a caixa, pontos sem água ou com ar","d":"Após esvaziar e lavar a caixa, alguns pontos ficam fracos, tossindo ar ou sem água.","si":["Torneira tossindo ar","Ponto sem água após a limpeza","Jato falhando e espirrando","Barulho nos canos ao abrir"],"ca":["Ar preso na tubulação","Registro esquecido fechado","Sujeira no arejador","Respiro do barrilete obstruído","Válvula de descarga travada","Saída da caixa entupida"],"sis":"Água fria","fe":"Chave e balde","at":"Antes de trocar a peça","a":"Reabra os registros e purgue o ar antes de trocar peça: depois da limpeza, ar e sujeira são o normal."},{"n":98,"c":6,"t":"Boia elétrica não liga ou não desliga a bomba","d":"A bomba não liga com a caixa vazia, ou não desliga e a caixa transborda.","si":["Caixa vazia e bomba parada","Caixa transbordando pelo ladrão","Bomba ligando e desligando","Boia enroscada no cabo"],"ca":["Boia enroscada ou presa","Contrapeso no lugar errado","Ligação invertida da boia","Boia da cisterna desligando","Fio rompido ou emenda ruim","Boia com defeito interno"],"sis":"Elétrico e água","fe":"Multímetro (sem energia)","at":"Antes de trocar a peça","a":"Antes de condenar a bomba, olhe a boia: cabo enroscado e cisterna baixa param a bomba sem defeito nenhum."},{"n":99,"c":6,"t":"Caixa-d'água deformada ou com a base afundando","d":"A caixa estufou, entortou ou a base cedeu, e a tampa não fecha mais direito.","si":["Caixa estufada ou torta","Tampa não encaixa mais","Base de madeira cedendo","Vazamento na saída"],"ca":["Base sem apoio total","Madeiramento fraco ou podre","Caixa maior que a base","Calor e sol direto","Tubo forçando a caixa","Caixa velha ou de parede fina"],"sis":"Água fria","fe":"Nível e trena","at":"Antes de trocar a peça","a":"Mil litros de água pesam uma tonelada: corrija a base antes, senão a caixa nova deforma igual."},{"n":100,"c":6,"t":"Cisterna com nível baixando sem uso","d":"A cisterna perde nível de um dia para o outro, mesmo sem consumo na casa.","si":["Nível baixa sem consumo","Terreno úmido em volta","Marca de nível na parede","Conta de água mais alta"],"ca":["Trinca na cisterna","Bomba repondo perda de cima","Registro de limpeza passando","Passagem de tubo sem vedação","Impermeabilização vencida","Recalque do solo"],"sis":"Água fria","fe":"Trena e lanterna","at":"Antes de quebrar o piso","a":"Desligue a bomba e marque o nível antes de quebrar: a altura onde o nível para mostra onde está a trinca."},{"n":101,"c":7,"t":"Bomba liga mas não puxa água","d":"O motor gira e faz barulho, mas a água não sobe para a caixa ou sai só um fio.","si":["Motor ligado e caixa sem encher","Bomba roda em vazio, sem pressão","Sucção estala ou chupa ar","Parou depois de faltar água"],"ca":["Bomba perdeu a escorva","Ar entrando na sucção","Válvula de pé travada ou furada","Nível baixo na cisterna","Crivo ou filtro entupido","Altura de sucção acima do limite"],"sis":"Recalque","fe":"Balde e chave de boca","at":"Antes de trocar a peça","a":"Bomba que gira e não puxa muitas vezes perdeu a escorva ou chupa ar. Teste isso antes de condenar o motor."},{"n":102,"c":7,"t":"Bomba não liga","d":"A boia pede água, mas a bomba fica muda: sem ronco, sem vibração, sem nada.","si":["Caixa vazia e bomba parada","Nenhum ronco ao ligar","Disjuntor às vezes desarmado","Às vezes só um zumbido"],"ca":["Disjuntor desarmado ou sem energia","Boia elétrica não manda ligar","Capacitor da bomba queimado","Protetor térmico desarmado","Fio rompido ou emenda solta","Motor ou rotor travado"],"sis":"Elétrica da bomba","fe":"Multímetro","at":"Antes de trocar a peça","a":"Bomba muda nem sempre é motor queimado: confira disjuntor, boia e tensão antes de mandar rebobinar."},{"n":103,"c":7,"t":"Bomba liga e desliga rápido com a torneira aberta","d":"Com um ponto aberto, o pressurizador fica ligando e desligando a cada poucos segundos.","si":["Liga e desliga sem parar no banho","Jato pulsando no chuveiro","Estalo do pressostato toda hora","Motor mais quente que antes"],"ca":["Tanque de pressão sem ar","Membrana do tanque furada","Pressostato desregulado","Vazão abaixo da mínima","Ar na tubulação","Retenção ou sensor com defeito"],"sis":"Pressurização","fe":"Calibrador de pneu","at":"Antes de trocar a peça","a":"Antes de trocar bomba ou pressostato, calibre o tanque. Sem ar no tanque, o pressurizador fica ciclando."},{"n":104,"c":7,"t":"Pressurizador liga sozinho com a casa parada","d":"Ninguém usa água e o pressurizador parte sozinho de tempos em tempos, de dia ou de noite.","si":["Bomba parte de madrugada","Ninguém abriu nenhum ponto","Liga por segundos e desliga","Conta de luz mais alta"],"ca":["Descarga passando água","Torneira ou chuveiro pingando","Retenção não veda","Vazamento oculto na rede","Tanque de pressão sem ar","Pressostato ou sensor falhando"],"sis":"Pressurização","fe":"Corante e manômetro","at":"Antes de trocar a peça","a":"Pressurizador que liga sozinho está avisando que tem perda de água. Ache a perda antes de trocar o pressostato."},{"n":105,"c":7,"t":"Bomba fazendo barulho alto ou chiando","d":"A bomba funciona, mas ronca, chia, vibra ou faz barulho de pedrinha rodando dentro.","si":["Barulho de pedrinha dentro da bomba","Chiado agudo no motor","Bomba vibrando na base","Barulho piorou com o tempo"],"ca":["Cavitação na sucção","Base solta ou sem calço","Ar entrando na sucção","Rolamento do motor gasto","Tubo encostado ou sem apoio","Rotor raspando na carcaça"],"sis":"Bombeamento","fe":"Chave de boca e lanterna","at":"Antes de trocar a peça","a":"Barulho de pedrinha costuma ser cavitação, não motor. Libere a sucção antes de trocar a bomba."},{"n":106,"c":7,"t":"Bomba esquentando e desarmando","d":"A bomba trabalha um tempo, fica quente demais e desliga sozinha ou derruba o disjuntor.","si":["Carcaça quente demais ao toque","Desliga sozinha e volta depois","Disjuntor desarmando","Cheiro de quente no motor"],"ca":["Trabalhando a seco","Local abafado, sem ventilação","Capacitor fraco","Tensão baixa na rede","Partidas seguidas demais","Eixo pesado ou rolamento gasto"],"sis":"Elétrica da bomba","fe":"Alicate amperímetro","at":"Antes de trocar a peça","a":"Motor que esquenta muitas vezes é vítima: falta de água, tensão baixa ou partidas demais. Ache a causa antes."},{"n":107,"c":7,"t":"Bomba funciona, mas a caixa de cima demora a encher","d":"A bomba liga e manda água, mas leva muito mais tempo que antes para encher a caixa.","si":["Caixa enche bem mais devagar","Bomba ligada por muito tempo","Jato fraco na entrada da caixa","Piorou aos poucos"],"ca":["Crivo ou sucção entupidos","Registro meio fechado na linha","Vazamento no recalque","Ar entrando na sucção","Rotor gasto ou com sujeira","Bomba fraca para a altura"],"sis":"Recalque","fe":"Cronômetro e manômetro","at":"Antes de trocar a peça","a":"Antes de vender bomba nova, limpe o crivo e procure vazamento no recalque. Bomba velha costuma estar só sufocada."},{"n":108,"c":7,"t":"Bomba vazando pelo eixo","d":"Pinga ou escorre água entre o corpo da bomba e o motor, embaixo do eixo.","si":["Água pingando entre bomba e motor","Poça embaixo da bomba","Ferrugem no eixo ou na base","Pinga mais com a bomba ligada"],"ca":["Selo mecânico gasto","Selo queimado por rodar a seco","Areia ou sujeira no selo","Junta ou anel da carcaça","Conexão de cima pingando","Carcaça trincada"],"sis":"Bombeamento","fe":"Chave de boca e lanterna","at":"Antes de trocar a peça","a":"Seque a bomba e ache a primeira gota. Muitas vezes a água vem da conexão de cima e escorre até o eixo."},{"n":109,"c":7,"t":"Pressurizador não liga quando abre o chuveiro","d":"Abre o chuveiro e a água sai só por gravidade, fraca, sem o pressurizador partir.","si":["Chuveiro fraco como sem bomba","Pressurizador mudo ao abrir","Às vezes liga só em ponto grande","Caixa-d'água com água"],"ca":["Vazão abaixo da mínima","Ar preso no pressurizador","Sem energia na tomada","Caixa vazia ou registro fechado","Sensor de fluxo travado","Pressostato ou placa com defeito"],"sis":"Pressurização","fe":"Multímetro","at":"Antes de trocar a peça","a":"Teste com o chuveiro todo aberto e sem ar no aparelho. Muito pressurizador é trocado porque o ponto é pequeno."},{"n":110,"c":7,"t":"Bomba do poço puxando ar ou areia","d":"A água do poço sai com ar, cuspindo, ou com areia e barro no fundo do balde.","si":["Torneiras cuspindo ar","Areia no fundo do balde","Vazão cai depois de um tempo","Piora na época de seca"],"ca":["Nível do poço baixou","Bomba tira mais que o poço dá","Bomba perto do fundo","Tubo furado ou emenda solta","Filtro do poço danificado","Ar na sucção da bomba de cima"],"sis":"Poço","fe":"Balde e sonda de nível","at":"Antes de trocar a peça","a":"Bomba puxando ar muitas vezes é poço sem água para aquela vazão. Meça o nível antes de trocar a bomba."},{"n":111,"c":8,"t":"Batida forte no cano ao fechar a torneira","d":"Um tranco seco ecoa na parede quando fecha a torneira, a descarga ou a máquina de lavar.","si":["Pancada na parede ao fechar","Pior com a válvula de descarga","Batida quando a máquina enche","Cano tremendo no forro"],"ca":["Fechamento rápido demais","Pressão alta na rede","Válvula de descarga mal regulada","Tubo solto sem abraçadeira","Ar preso ou boia batendo","Falta de amortecedor de golpe"],"sis":"Água fria","fe":"Manômetro","at":"Antes de quebrar a parede","a":"Golpe de aríete raramente é cano quebrado: ache o ponto que fecha de vez e meça a pressão antes de abrir."},{"n":112,"c":8,"t":"Assovio ou zumbido no cano ao abrir a água","d":"Ao abrir um ponto, a tubulação apita, assobia ou zumbe enquanto a água corre.","si":["Apito ao abrir a torneira","Zumbido que muda com a abertura","Some ao abrir tudo","Barulho quando a caixa enche"],"ca":["Registro meio aberto","Vedante ou reparo solto","Boia enchendo a caixa","Pressão alta na rede","Conexão ou tubo estrangulado","Pressurizador vibrando"],"sis":"Água fria","fe":"Manômetro","at":"Antes de quebrar a parede","a":"Assovio costuma nascer num registro, numa boia ou num reparo. Teste ponto por ponto antes de abrir parede."},{"n":113,"c":8,"t":"Barulho de água correndo na parede com tudo fechado","d":"Ninguém usa água e dá para ouvir água correndo dentro da parede ou do piso.","si":["Chiado contínuo dentro da parede","Mais fácil de ouvir à noite","Nenhuma mancha aparente","Hidrômetro pode estar girando"],"ca":["Descarga passando água","Boia da caixa enchendo","Vazamento em tubo embutido","Esgoto do vizinho ou prumada","Pressurizador partindo","Água quente circulando"],"sis":"Água fria e esgoto","fe":"Haste de escuta","at":"Antes de quebrar a parede","a":"Barulho de água nem sempre é cano furado: pode ser a descarga ou o esgoto do vizinho. Teste antes de abrir."},{"n":114,"c":8,"t":"Cheiro de esgoto vindo do forro ou da parede","d":"O cheiro de esgoto vem de cima ou de dentro da parede, longe de ralo ou de vaso.","si":["Cheiro forte perto do forro","Nenhum ralo por perto","Piora quando usam o banheiro","Mancha escura no forro"],"ca":["Ventilação aberta no forro","Junta do tubo de queda vazando","Tubo de esgoto trincado","Ralo seco no andar de cima","Emenda de esgoto improvisada","Animal morto no forro"],"sis":"Esgoto","fe":"Lanterna e fumaça","at":"Antes de quebrar a parede","a":"Suba no forro antes de quebrar: ventilação terminando no forro é causa frequente e não exige abrir parede."},{"n":115,"c":8,"t":"Estalos na parede quando usa água quente","d":"Ao abrir a água quente, a parede ou o forro dá estalos secos que repetem até esfriar.","si":["Estalos ao abrir a água quente","Repete quando o cano esfria","Barulho no forro ou na parede","Pior no banho longo"],"ca":["Dilatação do tubo","Abraçadeira apertada demais","Tubo encostado na alvenaria","Trecho reto longo sem folga","Temperatura alta demais","Tubo comum em água quente"],"sis":"Água quente","fe":"Termômetro","at":"Antes de quebrar a parede","a":"Estalo de água quente é dilatação, não vazamento. Ajuste temperatura e fixação antes de pensar em abrir."},{"n":116,"c":8,"t":"Água amarelada ou com gosto de ferrugem","d":"A água sai amarela, marrom ou com gosto de ferro em alguns pontos ou na casa toda.","si":["Água amarela ao abrir de manhã","Gosto ou cheiro de ferro","Mancha marrom na louça","Às vezes só na água quente"],"ca":["Cano galvanizado enferrujado","Caixa-d'água suja","Rede pública após manutenção","Boiler ou aquecedor com sedimento","Água parada na tubulação","Poço com ferro dissolvido"],"sis":"Água fria e quente","fe":"Copo transparente","at":"Antes de quebrar a parede","a":"Confirme no copo se a cor vem da rua, da caixa ou do boiler antes de trocar a tubulação da casa."},{"n":117,"c":8,"t":"Ponto que às vezes tem água e às vezes não","d":"Um ponto fica sem água em alguns momentos e volta sozinho, sem padrão claro.","si":["Ponto seca e volta sozinho","Sai ar quando a água volta","Outros pontos com água","Pior em horário de pico"],"ca":["Ar preso no barrilete ou ramal","Ponto ligado direto na rua","Saída alta na caixa-d'água","Gaveta do registro solta","Sujeira indo e voltando no tubo","Boia fechando cedo demais"],"sis":"Água fria","fe":"Manômetro","at":"Antes de trocar a peça","a":"Falha que vai e volta raramente é peça quebrada: ar preso e ponto ligado direto na rua são os suspeitos."},{"n":118,"c":8,"t":"Máquina de lavar enche devagar ou dá erro de água","d":"A máquina demora para encher, para no meio do ciclo ou mostra aviso de falta de água.","si":["Máquina leva muito para encher","Aviso de falta de água no painel","Ciclo para no enchimento","Outros pontos com água normal"],"ca":["Filtro da entrada entupido","Torneira da máquina meio fechada","Mangueira dobrada ou esmagada","Pressão baixa no ponto","Sujeira ou ar no ramal","Válvula de entrada da máquina"],"sis":"Água fria","fe":"Balde e cronômetro","at":"Antes de trocar a peça","a":"Antes de culpar a máquina, encha um balde pela torneira e limpe o filtro da entrada. Muitas vezes é só isso."},{"n":119,"c":8,"t":"Choque ao encostar na torneira ou no registro","d":"A pessoa leva choque ou sente formigamento ao tocar a torneira, o registro ou a água.","si":["Choque ao tocar a torneira","Formigamento na água do banho","Pior com o chuveiro ligado","O disjuntor não desarma"],"ca":["Chuveiro elétrico com fuga","Falta de aterramento","Torneira elétrica com defeito","Aquecedor elétrico ou boiler","Fio encostado em cano metálico","Fuga na rede elétrica da casa"],"sis":"Elétrica e água","fe":"Eletricista habilitado","at":"Antes de trocar a peça","a":"Choque na água é problema elétrico. Não troque torneira nem registro: desligue tudo e chame o eletricista."},{"n":120,"c":8,"t":"Água sai branca, leitosa, e clareia no copo","d":"A água sai esbranquiçada, como leite, e vai clareando no copo depois de alguns segundos.","si":["Água branca ao sair da torneira","Clareia de baixo para cima","Comum depois de falta de água","Às vezes sai junto com ar"],"ca":["Ar dissolvido na água","Ar na rede depois de manutenção","Pressurizador puxando ar","Arejador misturando ar","Água quente liberando ar","Cal ou sedimento em suspensão"],"sis":"Água fria","fe":"Copo transparente","at":"Antes de trocar a peça","a":"Água branca que clareia no copo é ar, não sujeira. Faça o teste antes de trocar filtro, caixa ou tubulação."}];
